import{z as o,x as B,o as E,c as d,q as n,j as l,D as t,d as r,s as i,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"功耗：动态与静态","description":"","frontmatter":{"title":"功耗：动态与静态","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/power-dynamic-static.md","filePath":"cs/power-dynamic-static.md","lastUpdated":1791063341000}'),p={name:"cs/power-dynamic-static.md"};function C(m,a,D,h,f,c){const s=B("Mermaid");return E(),d("div",null,[a[2]||(a[2]=n('<h1 id="功耗-动态与静态" tabindex="-1">功耗：动态与静态 <a class="header-anchor" href="#功耗-动态与静态" aria-label="Permalink to &quot;功耗：动态与静态&quot;">​</a></h1><div class="epigraph"><p>动态功耗随 $CV^2f$ 与翻转率走；静态是漏电，关断时钟也还在漏。算术单元的华莱士树既贡献电容，也贡献每拍翻转。</p><footer>—— 据 Rabaey, Chandrakasan, Nikolic, Digital Integrated Circuits；Weste and Harris, CMOS VLSI Design；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/asic-flow-stdcell">上一课</a>让网表落到带电容的金属与扩散区。<a href="/cs/sta">STA</a> 只管时序。缺口是<strong>功耗分解</strong>：动态（开关、短路）与静态（亚阈值、栅漏），否则下一课门控与 DVFS 没有作用对象。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CMOS 动态：\\(P_{\\mathrm{dyn}}\\approx \\alpha C V^2 f\\)。\\(\\alpha\\) 是活动因子，FMA 阵列每拍大翻转则 \\(\\alpha\\) 高。<span class="marginnote">数字实例：公式里电压是<strong>平方</strong>项，这是「降压最有效」的来历。电压降 \\(10\\%\\)（比如 \\(1.0\\,\\mathrm{V}\\to 0.9\\,\\mathrm{V}\\)），动态功耗变成 \\(0.9^2=0.81\\)，直接省约 \\(19\\%\\)；而降频 \\(10\\%\\) 只省 \\(10\\%\\)。代价是门变慢，时序分析要重做——省电从来不是免费的。</span>短路功耗在边沿转换时 PMOS/NMOS 同时导通。静态：沟道漏电随阈值与温度，工艺缩小后可与动态同量级。缺口不是再讲标准单元行，而是这几项如何进设计决策：降 \\(V\\) 最有效，但延迟变差，STA 要重做。</p><p>FPGA LUT 配置 SRAM 也漏电；ASIC 标准单元按阈值分 HVT/LVT 库做漏电–速度权衡。</p><h3 id="降频不是唯一旋钮" tabindex="-1">降频不是唯一旋钮 <a class="header-anchor" href="#降频不是唯一旋钮" aria-label="Permalink to &quot;降频不是唯一旋钮&quot;">​</a></h3><p>\\(P\\propto f\\) 只抓住动态。漏电与 \\(f\\) 无关，待机芯片仍热。把功耗问题全交给「时钟调慢」，静态主导的节点无效。面积更大的并行（多份 ALU）可降 \\(f\\) 保持吞吐，但 \\(C\\) 上升，需要算总账——阿姆达尔与功耗墙后课再收。</p><p><span class="marginnote">Rabaey DIC 与 Weste/Harris 给 CMOS 功耗公式。CA:AQA 把功耗作为体系结构约束。本课不进入电源管理 IC 的模拟设计。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>估计：从 RTL/网表切换活动（仿真或向量）× 电容模型。时钟网本身是巨大 \\(C\\)，故 <a href="/cs/clock-skew-cts">CTS</a> 也是功耗问题。算术：饱和 MUX 比浮点 LZC 轻；双精度 FMA 是功耗大户。报告分开关、内部、漏电。</p>',11)),(E(),l(A,null,{default:t(()=>[i(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SW%5B%22%CE%B1%20C%20V%C2%B2%20f%20%E5%BC%80%E5%85%B3%22%5D%20--%3E%20TOT%5B%22%E6%80%BB%E5%8A%9F%E8%80%97%22%5D%0A%20%20SC%5B%22%E7%9F%AD%E8%B7%AF%22%5D%20--%3E%20TOT%0A%20%20LEAK%5B%22%E6%BC%8F%E7%94%B5%E9%9D%99%E6%80%81%22%5D%20--%3E%20TOT%0A%20%20TOT%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%97%A8%E6%8E%A7%E4%B8%8E%20DVFS%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：时钟网像全城喇叭广播——不管每家有没有货要出，喇叭每拍都喊一遍，人人都要竖耳听一次。所以时钟树是芯片上最大的「常翻转变量」，这也解释了为什么下一课的门控（分区关喇叭）是第一杠杆：空闲模块连喇叭都停掉，\\(\\alpha\\) 就地归零。")],-1)),a[4]||(a[4]=e("p",null,"温度反馈：更热则漏电更大，STA 的慢角与功耗的热角要一起看。",-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"下一课时钟门控降 \\(\\alpha\\) 中的时钟翻转；DVFS 降 \\(V\\) 与 \\(f\\)。Dennard 缩放解释为何电压不能随工艺无限降。本课只钉两项之和。验证与 DFT 扫描时翻转率异常高，功耗签核要分功能模式与测试模式。",-1)),a[7]||(a[7]=e("p",null,"面对一个功耗问题该动哪个旋钮，取决于超支的是哪一项：",-1)),(E(),l(A,null,{default:t(()=>[i(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E5%8A%9F%E8%80%97%E8%B6%85%E6%94%AF%E5%9C%A8%E5%93%AA%E4%B8%80%E9%A1%B9%3F%22%7D%20--%3E%20A%5B%22%E5%8A%A8%E6%80%81%E4%B8%BA%E4%B8%BB%EF%BC%8C%E7%BF%BB%E8%BD%AC%E5%A4%AA%E5%A4%9A%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E9%9D%99%E6%80%81%E4%B8%BA%E4%B8%BB%EF%BC%8C%E5%BE%85%E6%9C%BA%E6%BC%8F%E7%94%B5%E5%A4%A7%22%5D%0A%20%20A%20--%3E%20C%5B%22%E6%97%B6%E9%92%9F%E9%97%A8%E6%8E%A7%E5%8E%8B%E6%B4%BB%E5%8A%A8%E5%9B%A0%E5%AD%90%20%CE%B1%22%5D%0A%20%20A%20--%3E%20D%5B%22DVFS%20%E9%99%8D%20V%20%E4%B8%8E%20f%22%5D%0A%20%20B%20--%3E%20E%5B%22%E9%80%89%E9%AB%98%E9%98%88%E5%80%BC%E5%8D%95%E5%85%83%20HVT%20%E6%8D%A2%E6%BC%8F%E7%94%B5%22%5D%0A%20%20B%20--%3E%20F%5B%22%E5%85%B3%E6%96%AD%E7%94%B5%E6%BA%90%E5%9F%9F%22%5D%0A%20%20C%20--%3E%20G%5B%22%E9%87%8D%E8%B7%91%E6%97%B6%E5%BA%8F%E4%B8%8E%E9%AA%8C%E8%AF%81%22%5D%0A%20%20D%20--%3E%20G%0A%20%20E%20--%3E%20G%0A%20%20F%20--%3E%20G%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=n('<p><span class="marginnote">常见误区：初学者容易以为「芯片闲着就不耗电」。漏电一项只看工艺、阈值与温度，时钟停了它照漏——这就是待机芯片仍发烫、手机放一夜也掉电的原因之一。对付静态功耗要的是关电源域或换高阈值单元，调频率对它完全无效。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不推导亚阈值电流公式的全部器件物理，不写封装热阻网络的有限元。不把数据中心电费表当课程。不进入限价簿或模型训练的能源口号，只谈芯片上的 \\(C,V,f\\)。</p><p>后课默认：动态随 \\(CV^2f\\alpha\\)，静态是漏电；二者都要管。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>动态：\\(CV^2f\\) 与翻转；静态：漏电，与时钟无关。</li><li>降压最有效但伤时序。</li><li>时钟树与宽算术阵列是电容大户。</li><li>出处：Rabaey et al.；Weste and Harris；Hennessy and Patterson, CA:AQA。</li></ul>',6))])}const F=o(p,[["render",C]]);export{u as __pageData,F as default};
